<template>
  <view class="container">
    <!-- 顶部导航栏 -->
    <view class="header">
      <view class="header-left" @click="goBack">
        <uni-icons type="left" size="24" color="#ffffff"></uni-icons>
      </view>
      <text class="header-title">发送消息</text>
    </view>
    
    <!-- 选择接收者类型 -->
    <view class="content">
      <view class="section">
        <text class="section-title">选择接收者类型</text>
        <view class="type-selector">
          <view 
            class="type-item" 
            :class="{ active: receiverType === '0' }"
            @click="selectReceiverType('0')"
          >
            <uni-icons type="person" size="32" :color="receiverType === '0' ? '#ff6b35' : '#999'"></uni-icons>
            <text class="type-label">用户</text>
          </view>
          <view 
            class="type-item" 
            :class="{ active: receiverType === '1' }"
            @click="selectReceiverType('1')"
          >
            <uni-icons type="shop" size="32" :color="receiverType === '1' ? '#ff6b35' : '#999'"></uni-icons>
            <text class="type-label">商家</text>
          </view>
        </view>
      </view>
      
      <!-- 输入接收者ID -->
      <view class="section">
        <text class="section-title">接收者ID</text>
        <input 
          class="input-field" 
          v-model="receiverId" 
          placeholder="请输入接收者ID"
          type="number"
        />
      </view>
      
      <!-- 发送按钮 -->
      <view class="send-section">
        <button class="send-btn" @click="startChat" :disabled="!receiverId || !receiverType">
          开始聊天
        </button>
      </view>
    </view>
  </view>
</template>

<script lang="ts" setup>
import { ref, onMounted } from 'vue';

// 当前用户信息
const currentUserId = ref(1); // 实际应从登录信息获取
const currentUserType = ref('0'); // 0=用户, 1=商家

// 从缓存加载当前用户信息
onMounted(() => {
  const cachedUserId = uni.getStorageSync('userId');
  const cachedUserType = uni.getStorageSync('userType');
  
  if (cachedUserId) {
    currentUserId.value = parseInt(cachedUserId);
  }
  if (cachedUserType) {
    currentUserType.value = cachedUserType;
  }
});

// 接收者信息
const receiverId = ref('');
const receiverType = ref('');

// 选择接收者类型
const selectReceiverType = (type: string) => {
  receiverType.value = type;
};

// 开始聊天
const startChat = () => {
  if (!receiverId.value || !receiverType.value) {
    uni.showToast({
      title: '请填写完整信息',
      icon: 'none'
    });
    return;
  }
  
  // 跳转到聊天页面
  uni.navigateTo({
    url: `/pages/chat/chat?senderId=${currentUserId.value}&senderType=${currentUserType.value}&receiverId=${receiverId.value}&receiverType=${receiverType.value}`
  });
};

// 返回
const goBack = () => {
  uni.navigateBack();
};
</script>

<style>
page {
  height: 100%;
  background-color: #fffdf8;
}

.container {
  height: 100%;
  display: flex;
  flex-direction: column;
  background-color: #fffdf8;
}

.header {
  width: 100%;
  height: 88rpx;
  background: linear-gradient(to right, #ff8c42, #ff6b35);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  box-sizing: border-box;
}

.header-left {
  position: absolute;
  left: 20rpx;
  padding: 10rpx;
}

.header-title {
  font-size: 36rpx;
  color: #ffffff;
  font-weight: bold;
}

.content {
  flex: 1;
  padding: 40rpx 30rpx;
  box-sizing: border-box;
  overflow-y: auto;
}

.section {
  margin-bottom: 40rpx;
}

.section-title {
  font-size: 32rpx;
  color: #333;
  font-weight: bold;
  margin-bottom: 20rpx;
  display: block;
}

.type-selector {
  display: flex;
  gap: 30rpx;
}

.type-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 30rpx;
  background-color: #ffffff;
  border-radius: 20rpx;
  border: 2rpx solid #f0f0f0;
  transition: all 0.3s;
}

.type-item.active {
  border-color: #ff6b35;
  background-color: #fff5f0;
}

.type-label {
  font-size: 28rpx;
  color: #666;
  margin-top: 10rpx;
}

.type-item.active .type-label {
  color: #ff6b35;
  font-weight: bold;
}

.input-field {
  width: 100%;
  height: 80rpx;
  padding: 0 30rpx;
  background-color: #ffffff;
  border-radius: 20rpx;
  border: 2rpx solid #f0f0f0;
  font-size: 28rpx;
  box-sizing: border-box;
}

.input-field:focus {
  border-color: #ff6b35;
}

.send-section {
  margin-top: 60rpx;
}

.send-btn {
  width: 100%;
  height: 88rpx;
  background: linear-gradient(to right, #ff8c42, #ff6b35);
  border: none;
  border-radius: 44rpx;
  color: #ffffff;
  font-size: 32rpx;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
}

.send-btn[disabled] {
  background: #cccccc;
  opacity: 0.6;
}
</style>

